INSERT INTO DimTrade (TradeID, SK_BrokerID, SK_CreateDateID, SK_CreateTimeID, SK_CloseDateID, SK_CloseTimeID, Status, DT_Type, CashFlag, SK_SecurityID, SK_CompanyID, Quantity, BidPrice, SK_CustomerID, SK_AccountID, ExecutedBy, TradePrice, Fee, Commission, Tax, BatchID) WITH DimTradeStaging AS (SELECT T.T_ID AS TradeID, 1 AS SK_BrokerID, COALESCE(CASE WHEN (TH.TH_ST_ID = 'SBMT' AND T.T_TT_ID IN ('TMB', 'TMS')) OR TH.TH_ST_ID = 'PNDG' THEN TH.TH_DTS WHEN TH.TH_ST_ID IN ('CMPT', 'CNCL') THEN NULL END, TH.TH_DTS) AS SK_CreateDateID, COALESCE(CASE WHEN (TH.TH_ST_ID = 'SBMT' AND T.T_TT_ID IN ('TMB', 'TMS')) OR TH.TH_ST_ID = 'PNDG' THEN TH.TH_DTS WHEN TH.TH_ST_ID IN ('CMPT', 'CNCL') THEN NULL END, TH.TH_DTS) AS SK_CreateTimeID, CASE WHEN (TH.TH_ST_ID = 'SBMT' AND T.T_TT_ID IN ('TMB', 'TMS')) OR TH.TH_ST_ID = 'PNDG' THEN NULL WHEN TH.TH_ST_ID IN ('CMPT', 'CNCL') THEN TH.TH_DTS END AS SK_CloseDateID, CASE WHEN (TH.TH_ST_ID = 'SBMT' AND T.T_TT_ID IN ('TMB', 'TMS')) OR TH.TH_ST_ID = 'PNDG' THEN NULL WHEN TH.TH_ST_ID IN ('CMPT', 'CNCL') THEN TH.TH_DTS END AS SK_CloseTimeID, ST.ST_NAME AS Status, TT.TT_NAME AS DT_Type, CASE WHEN T.T_IS_CASH = '1' THEN TRUE ELSE FALSE END AS CashFlag, 1 AS SK_SecurityID, 1 AS SK_CompanyID, T.T_QTY AS Quantity, T.T_BID_PRICE AS BidPrice, 1 AS SK_CustomerID, CAST(T.T_CA_ID AS INT) AS SK_AccountID, T.T_EXEC_NAME AS ExecutedBy, T.T_TRADE_PRICE AS TradePrice, T.T_CHRG AS Fee, T.T_COMM AS Commission, T.T_TAX AS Tax, 1 AS BatchID FROM Source.Trade AS T INNER JOIN Source.TradeHistory AS TH ON T.T_ID = TH.TH_T_ID INNER JOIN Source.StatusType AS ST ON T.T_ST_ID = ST.ST_ID INNER JOIN Source.TradeType AS TT ON T.T_TT_ID = TT.TT_ID) SELECT CAST(TradeID AS INT) AS TradeID, CAST(SK_BrokerID AS INT) AS SK_BrokerID, CAST((SELECT SK_DateID FROM DimDate WHERE DateValue = CAST(SK_CreateDateID AS DATE)) AS INT) AS SK_CreateDateID, CAST((SELECT SK_TimeID FROM DimTime WHERE TimeValue = CAST(SK_CreateTimeID AS TIME)) AS INT) AS SK_CreateTimeID, CAST((SELECT SK_DateID FROM DimDate WHERE DateValue = CAST(SK_CloseDateID AS DATE)) AS INT) AS SK_CloseDateID, CAST((SELECT SK_TimeID FROM DimTime WHERE TimeValue = CAST(SK_CloseTimeID AS TIME)) AS INT) AS SK_CloseTimeID, CAST(Status AS TEXT) AS Status, CAST(DT_Type AS TEXT) AS DT_Type, CAST(CashFlag AS BOOLEAN) AS CashFlag, CAST(SK_SecurityID AS INT) AS SK_SecurityID, CAST(SK_CompanyID AS INT) AS SK_CompanyID, CAST(Quantity AS DECIMAL(6, 0)) AS Quantity, CAST(BidPrice AS DECIMAL(8, 2)) AS BidPrice, CAST(SK_CustomerID AS INT) AS SK_CustomerID, CAST(SK_AccountID AS INT) AS SK_AccountID, CAST(ExecutedBy AS TEXT) AS ExecutedBy, CAST(TradePrice AS DECIMAL(8, 2)) AS TradePrice, CAST(Fee AS DECIMAL(10, 2)) AS Fee, CAST(Commission AS DECIMAL(10, 2)) AS Commission, CAST(Tax AS DECIMAL(10, 2)) AS Tax, CAST(BatchID AS DECIMAL(5, 0)) AS BatchID FROM DimTradeStaging;
